use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let mut numbers = Vec::with_capacity(n);
    for _ in 0..n {
        numbers.push(values.next().unwrap().parse::<i64>().unwrap());
    }

    let mut output = Vec::new();
    let mut start = 0;

    while start < n {
        let mut end = start;
        while end + 1 < n && numbers[end].checked_add(1) == Some(numbers[end + 1]) {
            end += 1;
        }

        if end - start + 1 >= 3 {
            output.push(format!("{}-{}", numbers[start], numbers[end]));
        } else {
            for number in &numbers[start..=end] {
                output.push(number.to_string());
            }
        }

        start = end + 1;
    }

    println!("{}", output.join(","));
}

