    if count == 0 {
        println!();
        return;
    }

    let first: i64 = values.next().unwrap().parse().unwrap();
    let mut start = first;
    let mut end = first;
    let mut output = String::new();

    for _ in 1..count {
        let value: i64 = values.next().unwrap().parse().unwrap();
        if end.checked_add(1) == Some(value) {
            end = value;
        } else {
            append_run(&mut output, start, end);
            start = value;
            end = value;
        }
    }

    append_run(&mut output, start, end);
    println!("{output}");
}

